# Patch 2026-09-08: Preis-Kernaussage — FDR-gesicherter Einzelkanal als eigener Fall
# Mit dem 5. Messtag reisst der Within-Effekt im Grounded-Kanal die FDR-Schwelle (q<0,05),
# das Mittel ueber alle Engines aber nicht. Vorher fiel das in den Marktmuster-Fall und wurde
# als blosser 'unkorrigierter Hinweis' abgetan. Jetzt eigener Satz + Zusatzzeile in der Karte.
# Idempotent: Signatur gOk.
import base64, sys
P = "dashboard_v3.html"
s = open(P, "rb").read()
if b"var gOk=(gWq!=null&&gWq<0.05);" in s:
    print("SKIP: bereits angewendet"); sys.exit(0)
PAARE = [
  ("",
   ""),
  ("",
   ""),
]
for a, n in PAARE:
    alt, neu = base64.b64decode(a), base64.b64decode(n)
    if s.count(alt) != 1:
        print("FEHLER: Alttext nicht exakt 1x:", alt[:70]); sys.exit(1)
    s = s.replace(alt, neu)
open(P, "wb").write(s)
print("OK: Preis-Kernaussage erweitert")
